import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it, vi } from 'vitest'
import { ApiError } from '../api'
import { AddIssueForm } from '../components/AddIssueForm'

async function fillIn(title: string, description: string, steps: string) {
  if (title) await userEvent.type(screen.getByLabelText('Title'), title)
  if (description) await userEvent.type(screen.getByLabelText('Description'), description)
  if (steps) await userEvent.type(screen.getByLabelText('Steps to reproduce'), steps)
}

describe('AddIssueForm', () => {
  it('has Title, Description, Steps to reproduce and Priority fields and an Add issue button', () => {
    render(<AddIssueForm onAdd={vi.fn()} />)
    expect(screen.getByLabelText('Title')).toBeInTheDocument()
    expect(screen.getByLabelText('Description')).toBeInTheDocument()
    expect(screen.getByLabelText('Steps to reproduce')).toBeInTheDocument()
    expect(screen.getByLabelText('Priority')).toHaveValue('medium')
    expect(screen.getByRole('button', { name: 'Add issue' })).toBeInTheDocument()
  })

  it('names every empty field and does not call onAdd', async () => {
    const onAdd = vi.fn()
    render(<AddIssueForm onAdd={onAdd} />)
    await userEvent.click(screen.getByRole('button', { name: 'Add issue' }))
    expect(screen.getByText('Title is required')).toBeInTheDocument()
    expect(screen.getByText('Description is required')).toBeInTheDocument()
    expect(screen.getByText('Steps to reproduce are required')).toBeInTheDocument()
    expect(onAdd).not.toHaveBeenCalled()
  })

  it('only complains about the field that is empty', async () => {
    render(<AddIssueForm onAdd={vi.fn()} />)
    await fillIn('A title', '', 'Some steps')
    await userEvent.click(screen.getByRole('button', { name: 'Add issue' }))
    expect(screen.getByText('Description is required')).toBeInTheDocument()
    expect(screen.queryByText('Title is required')).not.toBeInTheDocument()
    expect(screen.queryByText('Steps to reproduce are required')).not.toBeInTheDocument()
  })

  it('treats spaces only as empty', async () => {
    const onAdd = vi.fn()
    render(<AddIssueForm onAdd={onAdd} />)
    await fillIn('   ', 'A description', 'Some steps')
    await userEvent.click(screen.getByRole('button', { name: 'Add issue' }))
    expect(screen.getByText('Title is required')).toBeInTheDocument()
    expect(onAdd).not.toHaveBeenCalled()
  })

  it('calls onAdd with trimmed text and the chosen priority', async () => {
    const onAdd = vi.fn()
    render(<AddIssueForm onAdd={onAdd} />)
    await fillIn('  Dark mode flickers  ', ' It flashes white ', ' Reload the page ')
    await userEvent.selectOptions(screen.getByLabelText('Priority'), 'high')
    await userEvent.click(screen.getByRole('button', { name: 'Add issue' }))
    expect(onAdd).toHaveBeenCalledTimes(1)
    expect(onAdd).toHaveBeenCalledWith({
      title: 'Dark mode flickers',
      description: 'It flashes white',
      stepsToReproduce: 'Reload the page',
      priority: 'high',
    })
  })

  it('clears the boxes after a good add', async () => {
    render(<AddIssueForm onAdd={vi.fn()} />)
    await fillIn('A title', 'A description', 'Some steps')
    await userEvent.click(screen.getByRole('button', { name: 'Add issue' }))
    expect(screen.getByLabelText('Title')).toHaveValue('')
    expect(screen.getByLabelText('Description')).toHaveValue('')
    expect(screen.getByLabelText('Steps to reproduce')).toHaveValue('')
  })

  it('removes old problem messages once the form is good', async () => {
    render(<AddIssueForm onAdd={vi.fn()} />)
    await userEvent.click(screen.getByRole('button', { name: 'Add issue' }))
    expect(screen.getByText('Title is required')).toBeInTheDocument()
    await fillIn('A title', 'A description', 'Some steps')
    await userEvent.click(screen.getByRole('button', { name: 'Add issue' }))
    expect(screen.queryByText('Title is required')).not.toBeInTheDocument()
  })

  it('shows the server message and keeps what the person typed when the add fails', async () => {
    const onAdd = vi.fn().mockRejectedValue(new ApiError(403, 'Your role may not issue:create'))
    render(<AddIssueForm onAdd={onAdd} />)
    await fillIn('A title', 'A description', 'Some steps')
    await userEvent.click(screen.getByRole('button', { name: 'Add issue' }))
    expect(await screen.findByText('Your role may not issue:create')).toBeInTheDocument()
    expect(screen.getByLabelText('Title')).toHaveValue('A title')
  })

  it('says it could not reach the server when the failure is not an ApiError', async () => {
    const onAdd = vi.fn().mockRejectedValue(new TypeError('Failed to fetch'))
    render(<AddIssueForm onAdd={onAdd} />)
    await fillIn('A title', 'A description', 'Some steps')
    await userEvent.click(screen.getByRole('button', { name: 'Add issue' }))
    expect(await screen.findByText('Could not reach the server')).toBeInTheDocument()
  })

  it('starts with the values it is given, and uses a different button label, when editing', async () => {
    const onAdd = vi.fn()
    render(
      <AddIssueForm
        onAdd={onAdd}
        initial={{ title: 'Old title', description: 'Old description', stepsToReproduce: 'Old steps', priority: 'low' }}
        submitLabel="Save changes"
        clearOnSuccess={false}
      />,
    )
    expect(screen.getByLabelText('Title')).toHaveValue('Old title')
    expect(screen.getByLabelText('Priority')).toHaveValue('low')
    await userEvent.click(screen.getByRole('button', { name: 'Save changes' }))
    expect(onAdd).toHaveBeenCalledWith({
      title: 'Old title',
      description: 'Old description',
      stepsToReproduce: 'Old steps',
      priority: 'low',
    })
    expect(screen.getByLabelText('Title')).toHaveValue('Old title')
  })
})
